(window.RYADOM_I18N = window.RYADOM_I18N || {})["ar"] = {"strings":{"Разделы":"الأقسام","Сегодня":"اليوم","Мой дневник":"يومياتي","Места":"الأماكن","Игры":"الألعاب","Практики":"التمارين","Обо мне":"عنّي","Ты можешь идти в своём темпе.":"يمكنك أن تمضي على مهلك.","Здесь нет правильных ответов и обязательных серий дней.":"لا توجد هنا إجابات صحيحة ولا أيام متتالية إلزامية.","Пространство для себя":"مساحة لنفسك","Профиль":"الملف الشخصي","Как ты сегодня?":"كيف حالك اليوم؟","Можно честно. Начнём с того, что есть сейчас.":"يمكنك أن تكون صريحًا. لنبدأ بما هو موجود الآن.","С чего начать":"من أين تبدأ","Поговорить":"تحدّث","Своими словами, без правил":"بكلماتك، دون قواعد","Потренировать разговор":"تدرّب على محادثة","Начальник, мама, отказ, извинение":"المدير، الأم، الرفض، الاعتذار","Подобрать практику":"اختر تمرينًا","Подходящую сейчас":"المناسب الآن","Рядом":"Ryadom","На твоей стороне":"إلى جانبك","Напиши, что происходит…":"اكتب ما الذي يحدث…","Написать сообщение":"اكتب رسالة","Продиктовать сообщение":"أملِ رسالة","Отправить":"إرسال","Озвучивать ответы":"قراءة الردود بصوت عالٍ","На сегодня":"لهذا اليوم","Достаточно одного маленького шага":"خطوة صغيرة واحدة تكفي","Не нужно исправлять весь день целиком.":"لست بحاجة إلى إصلاح اليوم كله.","Твоё пространство":"مساحتك","Разговоры и отметки сохраняются только на этом устройстве.":"تُحفَظ المحادثات والتسجيلات على هذا الجهاز فقط.","Последняя отметка":"آخر تسجيل","Пока нет":"لا يوجد بعد","Открыть дневник →":"افتح اليوميات ←","✦ ПРАКТИКА ДНЯ":"✦ تمرين اليوم","После трудного разговора":"بعد محادثة صعبة","4–6 минут · пройти →":"4–6 دقائق · ابدأ ←","Только о тебе и твоём состоянии":"عنك وعن حالتك فقط","Разговоры, ощущения и места, в которых прошёл твой день. Игровые истории хранятся отдельно.":"المحادثات والمشاعر والأماكن التي مرّ بها يومك. قصص الألعاب تُحفَظ بشكل منفصل.","Календарь дня ↓":"تقويم الأيام ↓","7 дней":"7 أيام","30 дней":"30 يومًا","Как сегодня внутри?":"كيف تشعر في داخلك اليوم؟","Четыре отдельные отметки от 0 до 4. Это твои ощущения, а не медицинская оценка.":"أربع علامات منفصلة من 0 إلى 4. هذه مشاعرك وليست تقييمًا طبيًا.","Тревога":"القلق","совсем нет":"إطلاقًا","очень сильно":"قوي جدًا","Грусть":"الحزن","Беспокойство":"التوتر","Спокойствие":"الهدوء","Что запомнилось сегодня?":"ما الذي بقي في ذاكرتك اليوم؟","(необязательно)":"(اختياري)","Можно отмечать раз в день. Сегодняшнюю отметку можно изменить.":"يمكنك التسجيل مرة واحدة يوميًا. يمكن تعديل تسجيل اليوم.","Сохранить отметку":"حفظ التسجيل","Сильная тревога":"قلق شديد","Нет отметок":"لا توجد تسجيلات","Сильная грусть":"حزن شديد","Много спокойствия":"هدوء كبير","Как менялось состояние":"كيف تغيّرت حالتك","Каждая точка — твоя отметка за день. Пропуски не считаются нулём.":"كل نقطة هي تسجيلك ليوم واحد. الأيام الفائتة لا تُحسَب صفرًا.","Пока нет точек на графике. Поставь первую отметку выше.":"لا توجد نقاط على الرسم بعد. أضف أول تسجيل في الأعلى.","0 — совсем нет":"0 — إطلاقًا","4 — очень сильно":"4 — قوي جدًا","Что можно заметить":"ما يمكن ملاحظته","После трёх отметок здесь появится короткое наблюдение. Пропущенные дни не учитываются.":"بعد ثلاثة تسجيلات ستظهر هنا ملاحظة قصيرة. الأيام الفائتة لا تُحسَب.","Что помогает именно тебе":"ما الذي يساعدك أنت تحديدًا","Когда ты попробуешь практику и оценишь её, здесь появятся твои наблюдения.":"عندما تجرّب تمرينًا وتقيّمه، ستظهر ملاحظاتك هنا.","Стереть дневник":"مسح اليوميات","Календарь дня":"تقويم الأيام","Предыдущий месяц":"الشهر السابق","Следующий месяц":"الشهر التالي","Пн":"إث","Вт":"ث","Ср":"أر","Чт":"خ","Пт":"ج","Сб":"س","Вс":"أح","Синяя точка — разговор, зелёная — место. Цвет дня — настроение; другие точки — отметка ощущений. Игровые события сюда не попадают.":"النقطة الزرقاء: محادثة، والخضراء: مكان. لون اليوم: المزاج؛ النقاط الأخرى: تسجيل المشاعر. أحداث الألعاب لا تظهر هنا.","Пока нет записей за этот день. Можно добавить место, которое тебе запомнилось.":"لا توجد مدخلات لهذا اليوم بعد. يمكنك إضافة مكان تتذكره.","Места этого дня":"أماكن اليوم","Пока пусто":"فارغ حاليًا","Добавь посещённое место. Приложение не отслеживает перемещения автоматически.":"أضف مكانًا زرته. التطبيق لا يتتبع تنقلاتك تلقائيًا.","＋ Добавить место":"＋ أضف مكانًا","Места записываешь только ты. Они остаются на этом устройстве и не привязаны к игровому прогрессу.":"أنت وحدك من يسجّل الأماكن. تبقى على هذا الجهاز ولا ترتبط بتقدّم الألعاب.","Дневник хранится только на этом устройстве. Посещённые места добавляешь только ты; автоматического отслеживания перемещений нет.":"تُحفَظ اليوميات على هذا الجهاز فقط. أنت وحدك تضيف الأماكن التي زرتها؛ لا يوجد تتبّع تلقائي للموقع.","Место для этого момента":"مكان لهذه اللحظة","Куда под настроение?":"إلى أين حسب مزاجك؟","Иногда помогает сменить обстановку. Выбери, чего хочется сейчас, и посмотри места поблизости.":"أحيانًا يساعد تغيير الأجواء. اختر ما تريده الآن وشاهد الأماكن القريبة.","Какое настроение?":"ما المزاج؟","☁ Грустно":"☁ حزين","◌ Тревожно":"◌ قلق","♡ Романтично":"♡ رومانسي","✷ Весело":"✷ مرح","✿ Спокойно":"✿ هادئ","◇ Хочется нового":"◇ شيء جديد","☕ Устало":"☕ متعب","↗ Хочется общения":"↗ رغبة في الصحبة","Можно выбрать настроение, а потом указать город или разрешить определить примерное местоположение.":"اختر مزاجًا، ثم أدخل مدينة أو اسمح بتحديد موقع تقريبي.","Где искать?":"أين نبحث؟","Геолокация запрашивается только по нажатию и не записывается в дневник. Поиск по названию города показывает места около его центра.":"يُطلَب الموقع عند الضغط فقط ولا يُحفَظ في اليوميات. البحث باسم المدينة يعرض أماكن قرب مركزها.","⌖ Рядом со мной":"⌖ بالقرب مني","Или город / район":"أو مدينة / حي","Например, Тбилиси":"مثلًا، عمّان","Найти":"ابحث","Выбери настроение и место поиска.":"اختر مزاجًا ومكان البحث.","Место найдётся":"سنجد مكانًا","Выбери настроение и нажми «Рядом со мной» или введи город. Любимые места из дневника появятся здесь первыми.":"اختر مزاجًا واضغط «بالقرب مني» أو اكتب مدينة. ستظهر أماكنك المفضلة من اليوميات أولًا.","Порядок: сначала любимые, затем подходящие места по расстоянию. Рейтинги и популярность в соцсетях пока не доступны — мы не подменяем их количеством посещений.":"الترتيب: المفضلة أولًا، ثم الأماكن المناسبة حسب المسافة. التقييمات والشهرة على الشبكات غير متاحة بعد، ولا نستبدلها بعدد الزيارات.","Моё: что я люблю":"خاصّتي: ما أحبه","Работает без интернета. Если поиск мест недоступен, подсказки берутся отсюда и из раздела «Обо мне».":"يعمل دون إنترنت. إذا تعذّر البحث، تأتي الاقتراحات من هنا ومن «عنّي».","Пока пусто. Добавь любимое место, блюдо или занятие: подсказки станут точнее.":"فارغ حاليًا. أضف مكانًا أو طبقًا أو نشاطًا مفضلًا لتصبح الاقتراحات أدق.","Что добавить":"ماذا تضيف","Еда":"طعام","Место":"مكان","Занятие":"نشاط","например: кофейня у реки":"مثلًا، مقهى على النهر","Название или описание":"الاسم أو الوصف","Добавить":"أضف","Новые места: данные участников OpenStreetMap через Photon. Сведения могут быть неполными.":"أماكن جديدة: بيانات مساهمي OpenStreetMap عبر Photon. قد تكون المعلومات ناقصة.","Интерактивные истории":"قصص تفاعلية","Игры про жизнь":"ألعاب عن الحياة","Герои, разговоры и решения, после которых меняется история.":"شخصيات ومحادثات وقرارات تغيّر القصة.","Сюжетная игра · одна неделя":"لعبة قصصية · أسبوع واحد","Тихий город: неделя до ответа":"المدينة الهادئة: أسبوع قبل الرد (بالروسية)","Письмо о работе в другом городе, мама, папа, подруга и восемь слотов времени. На всё не хватит — и каждая встреча оставит след.":"عرض عمل في مدينة أخرى، وأم وأب وصديقة وثماني فترات زمنية. الوقت لا يكفي لكل شيء، وكل لقاء يترك أثرًا.","Одна неделя, восемь слотов, пять единиц сил":"أسبوع واحد، ثماني فترات، خمس وحدات طاقة","Начать историю →":"ابدأ القصة ←","Тренажёры разговоров":"تدريبات المحادثة","Квесты, где выбор слов меняет ход разговора. Опираются на известные методики общения.":"مهام يغيّر فيها اختيار الكلمات مسار المحادثة. مبنية على أساليب تواصل معروفة. حاليًا بالروسية فقط.","КВЕСТ · 6 ШАГОВ · 2 СТИЛЯ":"مهمة · 6 خطوات · نمطان","Разговор с начальником":"حديث مع المدير","Трудная обратная связь. Неудачный ответ оставляет на месте, удачный пускает дальше и называет приём, на котором он держится.":"ملاحظات صعبة. الإجابة الضعيفة تبقيك مكانك، والجيدة تدفعك للأمام وتسمّي الأسلوب الذي تقوم عليه.","Тренажёр разговора":"تدريب على المحادثة","КВЕСТ · 5 ШАГОВ · 2 СТИЛЯ":"مهمة · 5 خطوات · نمطان","Сказать «нет» коллеге":"قول «لا» لزميل","Отказать на просьбу о выходных так, чтобы не поссориться: пауза, спокойное «нет», держать решение, предложить своё.":"رفض طلب لعطلة نهاية الأسبوع دون شجار: توقّف، «لا» هادئة، تمسّك بقرارك، واقترح بديلك.","Границы на работе":"الحدود في العمل","Разговор с мамой о границах":"حديث مع الأم عن الحدود","Сохранить близость и право решать самому: признать чувства, сказать «я», договориться о понятном ритме.":"حافظ على القرب وعلى حقك في القرار: اعترف بالمشاعر، تحدّث بصيغة «أنا»، واتفقا على إيقاع واضح.","Границы в семье":"الحدود في العائلة","Извиниться и починить":"اعتذر وأصلح","Подвели близкого человека. Как извиниться конкретно, выслушать и предложить, что исправите.":"خذلت شخصًا قريبًا. كيف تعتذر بشكل محدد، وتستمع، وتقترح كيف تُصلح.","Конфликт и примирение":"الخلاف والمصالحة","Попросить о помощи":"طلب المساعدة","Попросить так, чтобы человеку было легко и согласиться, и отказать: конкретно, без извинений, с взаимностью.":"اطلب بطريقة تجعل الموافقة أو الرفض سهلين: بشكل محدد، دون إفراط في الاعتذار، ومع المعاملة بالمثل.","Просьбы":"الطلبات","Разговор о деньгах":"حديث عن المال","Обсудить неравные общие расходы без обвинений: факты, отражение, пропорциональное решение, срок сверки.":"ناقش المصاريف المشتركة غير المتكافئة دون لوم: حقائق، إعادة صياغة، حل متناسب، وموعد للمراجعة.","Деньги и близкие":"المال والمقرّبون","Сказать, что тебе нужно":"قل ما تحتاجه","Попросить больше времени вместе, не обвиняя: мягкий старт, «я»-сообщение, валидация, небольшой эксперимент.":"اطلب وقتًا أطول معًا دون لوم: بداية لطيفة، رسالة بصيغة «أنا»، تقدير للمشاعر، تجربة صغيرة.","Отношения":"العلاقات","Отказать другу":"رفض طلب صديق","Отказаться от поездки так, чтобы дружба не пострадала: пауза, тёплое «нет», повтор решения, альтернатива.":"ارفض رحلة دون أن تتأذّى الصداقة: توقّف، «لا» دافئة، كرّر قرارك، واقترح بديلًا.","Дружба и границы":"الصداقة والحدود","Другие сюжетные направления · 12 коротких историй":"قصص أخرى · 12 قصة قصيرة (بالروسية)","Границы без ссоры":"حدود بلا شجار","Учиться говорить о своих возможностях и желаниях.":"تعلّم الحديث عن قدراتك ورغباتك.","ИГРАТЬ · 2 ДНЯ":"العب · يومان","Тревога и неопределённость":"القلق وعدم اليقين","Отличать риск от тревожных предположений.":"التمييز بين الخطر الحقيقي والافتراضات القلقة.","ИГРАТЬ · 4 ГЛАВЫ":"العب · 4 فصول","Внутренний критик":"الناقد الداخلي","Находить более честный и бережный внутренний голос.":"العثور على صوت داخلي أصدق وألطف.","Сложный разговор":"محادثة صعبة","Тренировать фразы и слушать ответ собеседника.":"تدرّب على العبارات واستمع إلى ردّ الآخر.","Когда нет сил":"عندما لا تبقى طاقة","Планировать восстановление без гонки продуктивности.":"خطّط للتعافي دون سباق إنتاجية.","Свои решения":"قراراتك الخاصة","Замечать чужие ожидания и выбирать свой шаг.":"لاحظ توقعات الآخرين واختر خطوتك.","Отношения с собой":"علاقتك بنفسك","Собирать опоры, которые не зависят от оценки других.":"اجمع ركائز لا تعتمد على تقييم الآخرين.","Одиночество и близость":"الوحدة والقرب","Искать посильные способы установить контакт.":"ابحث عن طرق ممكنة للتواصل.","Работа и выгорание":"العمل والإنهاك","Замечать нагрузку и договариваться о границах.":"لاحظ حجم العمل واتفق على الحدود.","Потеря и перемены":"الفقد والتغيير","Давать место чувствам и искать поддержку.":"أفسح مجالًا للمشاعر وابحث عن الدعم.","Тело и забота":"الجسد والعناية","Замечать сигналы тела без оценивания внешности.":"لاحظ إشارات الجسد دون الحكم على المظهر.","Отделять свои потребности от требований других.":"افصل احتياجاتك عن مطالب الآخرين.","Первая история — полноценная, на том же движке, что «Тихий город». Остальные одиннадцать — короткие зарисовки на четыре сцены, их предстоит переписать так же.":"القصة الأولى كاملة، على المحرّك نفسه لـ«المدينة الهادئة». أما الإحدى عشرة الأخرى فمسودات قصيرة من أربعة مشاهد ستُعاد كتابتها بالطريقة نفسها.","Инструменты на каждый день":"أدوات لكل يوم","Библиотека практик":"مكتبة التمارين","Выбирай то, что подходит моменту. Можно пропустить любой шаг.":"اختر ما يناسب اللحظة. يمكنك تخطّي أي خطوة.","ПРАКТИКА В ФОКУСЕ · 4–6 МИНУТ":"تمرين مميّز · 4–6 دقائق","Когда слова ещё звучат в голове. Сначала найдём опору, затем разберём событие и выберем один посильный шаг.":"عندما ما زالت الكلمات تتردد في رأسك. نجد أولًا ما نستند إليه، ثم نفكّك ما حدث ونختار خطوة واحدة ممكنة.","01 · Опора":"01 · الاستناد","02 · Ясность":"02 · الوضوح","03 · Действие":"03 · الفعل","Попробовать практику →":"جرّب التمرين ←","Подходит сейчас":"مناسب الآن","Без сравнения":"بلا مقارنة","Заметь мысль «другие справляются лучше». Замени её на конкретный факт о сегодняшней нагрузке.":"لاحظ فكرة «الآخرون يتدبّرون أمورهم أفضل». استبدلها بحقيقة محددة عن عبء اليوم.","Работа":"العمل","Рабочая граница":"حدّ في العمل","Назови реалистичный срок и то, что потребуется, чтобы уложиться. Не обещай невозможного.":"حدّد موعدًا واقعيًا وما ستحتاجه للالتزام به. لا تَعِد بالمستحيل.","Злость":"الغضب","Граница одной фразой":"حدّ في جملة واحدة","Попробуй фразу: «Мне важно обсудить задачу, когда мы сможем говорить спокойно». Подстрой её под себя.":"جرّب العبارة: «من المهم لي أن نناقش المهمة عندما نستطيع الحديث بهدوء». عدّلها بما يناسبك.","Маршруты: несколько шагов подряд":"مسارات: عدة خطوات متتالية","После трудного разговора с начальником":"بعد محادثة صعبة مع المدير","практика":"تمرين","Вернуться в момент":"العودة إلى اللحظة","Отметить":"تحديد","После критики":"بعد النقد","Факты после встречи":"الحقائق بعد الاجتماع","тренажёр":"تدريب","Ответ начальнику":"الرد على المدير","Научиться говорить «нет»":"تعلّم قول «لا»","Пауза перед ответом":"توقّف قبل الرد","Право на нет":"الحق في الرفض","Сложный разговор с близким":"محادثة صعبة مع شخص قريب","Сначала услышать":"استمع أولًا","Я-сообщение":"رسالة «أنا»","Близость и границы":"القرب والحدود","Помириться после ссоры":"التصالح بعد شجار","Моя часть":"نصيبي من المسؤولية","Тёплое сообщение":"رسالة دافئة","Когда совсем нет сил":"عندما لا تبقى أي طاقة","Базовые нужды":"الاحتياجات الأساسية","Минимальный шаг":"أصغر خطوة","Просьба о помощи":"طلب المساعدة","Тихая прогулка":"نزهة هادئة","Спокойный вечер":"مساء هادئ","Вечерняя граница":"حدّ للمساء","Выгрузить мысли":"تفريغ الأفكار","Переход ко сну":"الانتقال إلى النوم","Поиск практики":"ابحث عن تمرين","Например: тревога, начальник, сон…":"مثلًا: قلق، مدير، نوم…","Все":"الكل","Перегрузка":"الإرهاق","Сон":"النوم","Нет сил":"بلا طاقة","Мысли":"الأفكار","Мягкое дыхание":"تنفّس لطيف","Замедлиться и почувствовать опору.":"تمهّل واشعر بما يسندك.","Переключить внимание на то, что вокруг.":"حوّل انتباهك إلى ما حولك.","Слова и границы":"الكلمات والحدود","Когда чужие слова задели слишком сильно.":"حين تجرحك كلمات أحدهم أكثر من اللازم.","Разложить по полочкам":"رتّب الأمور","Отделить событие от мыслей о нём.":"افصل الحدث عن أفكارك بشأنه.","Тёплая фраза":"عبارة دافئة","Поддержать себя без требования быть сильнее.":"ادعم نفسك دون أن تطالبها بأن تكون أقوى.","Смена обстановки":"تغيير الأجواء","Вода, движение или немного воздуха.":"ماء أو حركة أو قليل من الهواء.","Три опоры":"ثلاث ركائز","Оглянись и назови три устойчивых предмета рядом. Почувствуй стопы на полу. Сделай один удобный выдох.":"انظر حولك وسمِّ ثلاثة أشياء ثابتة قريبة. اشعر بقدميك على الأرض. أخرج زفيرًا مريحًا واحدًا.","Длинный выдох":"زفير طويل","Вдохни естественно, затем выдохни немного медленнее. Повтори несколько раз без задержки дыхания и без усилия.":"خذ شهيقًا طبيعيًا، ثم أخرج الزفير ببطء أكثر قليلًا. كرّر ذلك عدة مرات دون حبس النفس أو إجهاد.","Проверка фактов":"تحقّق من الحقائق","Запиши: что я знаю точно, что предполагаю и что могу уточнить. Не требуй от себя немедленного решения.":"اكتب: ما أعرفه يقينًا، وما أفترضه، وما يمكنني التحقق منه. لا تطلب من نفسك قرارًا فوريًا.","План на ближайший час":"خطة للساعة القادمة","Выбери одно безопасное и выполнимое действие на ближайший час. Остальное пока оставь на потом.":"اختر فعلًا واحدًا آمنًا وممكنًا للساعة القادمة. واترك الباقي لوقت لاحق.","Найди цвет":"ابحث عن لون","Выбери цвет и найди вокруг пять предметов этого цвета. Верни внимание к комнате, когда мысли ускоряются.":"اختر لونًا وابحث حولك عن خمسة أشياء بهذا اللون. أعد انتباهك إلى الغرفة كلما تسارعت أفكارك.","Контакт с поверхностью":"التلامس مع السطح","Заметь, как кресло или пол поддерживают тело. Опиши про себя три точки контакта.":"لاحظ كيف يسند الكرسي أو الأرض جسدك. صِف في سرّك ثلاث نقاط تلامس.","Язык":"اللغة","Язык интерфейса, практик и разговора. Квесты и сюжетные игры пока на русском.":"لغة الواجهة والتمارين والمحادثة. المهام والألعاب القصصية بالروسية حاليًا.","Только то, что рассказано тобой":"فقط ما شاركته أنت","Что обо мне известно":"ما هو معروف عنّي","Чтобы «Рядом» мог подсказать, куда сходить, что поесть и что поможет, ему нужно знать тебя. Здесь видно всё, что он помнит. Записи остаются только на этом устройстве: любую можно удалить.":"لكي يقترح Ryadom إلى أين تذهب وماذا تأكل وما الذي سيساعدك، عليه أن يعرفك. هنا يظهر كل ما يتذكره. تبقى المدخلات على هذا الجهاز فقط، ويمكن حذف أي منها.","Использовать в разговоре и подсказках":"الاستخدام في المحادثة والاقتراحات","Подтянуть из любимых мест":"استيراد من الأماكن المفضلة","Что люблю есть":"ما أحب أن آكله","блюда, кухня, вкусы":"أطباق، مطبخ، نكهات","например: тёплый суп, кофе с булочкой":"مثلًا: حساء دافئ، قهوة مع كعكة","Где мне хорошо":"أين أشعر بالراحة","места и обстановка":"أماكن وأجواء","например: набережная, тихая библиотека":"مثلًا: الكورنيش، مكتبة هادئة","Как люблю проводить время":"كيف أحب قضاء الوقت","занятия и ритм":"أنشطة وإيقاع","например: долгая прогулка, кино вечером":"مثلًا: مشي طويل، فيلم في المساء","Что помогает, когда тяжело":"ما يساعد حين يصعب الأمر","то, что правда работает":"ما ينجح فعلًا","например: горячий чай, музыка в наушниках":"مثلًا: شاي ساخن، موسيقى بالسماعات","С кем мне легко":"مع من أشعر بالارتياح","люди и формат общения":"أشخاص وطرق التواصل","например: с сестрой, один на один":"مثلًا: مع أختي، وجهًا لوجه","Чего лучше избегать":"ما الأفضل تجنّبه","что выматывает или раздражает":"ما يُرهق أو يُزعج","например: шумные места, спешка":"مثلًا: الأماكن الصاخبة، العجلة","Стереть всё, что обо мне записано":"امسح كل ما سُجّل عنّي","Дневник, места и игровой прогресс — отдельные данные: их очистка здесь не затрагивается.":"اليوميات والأماكن وتقدّم الألعاب بيانات منفصلة: المسح هنا لا يمسّها.","Моя активность за 7 дней":"نشاطي خلال 7 أيام","Считается только на этом устройстве и никуда не отправляется. Помогает понять, чем ты пользуешься.":"يُحسَب على هذا الجهاز فقط ولا يُرسَل إلى أي مكان. يساعدك على فهم ما تستخدمه.","Пока нет данных.":"لا توجد بيانات بعد.","Скопировать сводку":"انسخ الملخص","Сбросить счётчики":"إعادة ضبط العدّادات","Данные и конфиденциальность":"البيانات والخصوصية","Всё, что ты вводишь, остаётся на этом устройстве. Здесь можно посмотреть, что хранится, сохранить копию или удалить всё.":"كل ما تُدخله يبقى على هذا الجهاز. هنا يمكنك رؤية ما يُخزَّن، أو حفظ نسخة، أو حذف كل شيء.","Другие данные приложения":"بيانات أخرى للتطبيق","Сохранить копию файлом":"احفظ نسخة كملف","Скопировать текст":"انسخ كنص","Восстановить из файла":"استعادة من ملف","Файл с данными":"ملف البيانات","Восстановить из вставленного текста":"استعادة من نص ملصق","Удалить все мои данные":"احذف كل بياناتي","Как приложение обращается с данными":"كيف يتعامل التطبيق مع البيانات","Где хранятся.":"أين تُخزَّن.","В памяти браузера или приложения на этом устройстве. Учётных записей и серверной базы нет. Если очистить данные браузера или сменить устройство без копии, записи пропадут.":"في ذاكرة المتصفح أو التطبيق على هذا الجهاز. لا توجد حسابات ولا قاعدة بيانات على خادم. إذا مسحت بيانات المتصفح أو غيّرت الجهاز دون نسخة، ستضيع المدخلات.","Что передаётся наружу.":"ما يُرسَل إلى الخارج.","Поиск мест: текст запроса и, если разрешишь, примерные координаты уходят в сервисы карт OpenStreetMap (Photon, Nominatim). Режим с сервером и ИИ, если он подключён: текст твоих сообщений уходит на сервер и к ИИ-провайдеру, чтобы получить ответ. Голосовой ввод и озвучка используют службы устройства.":"البحث عن الأماكن: يُرسَل نص البحث، وإن سمحت، إحداثيات تقريبية إلى خدمات خرائط OpenStreetMap (Photon وNominatim). وضع الخادم والذكاء الاصطناعي إن كان مفعّلًا: يُرسَل نص رسائلك إلى الخادم ومزوّد الذكاء الاصطناعي للحصول على رد. الإدخال والقراءة الصوتيان يستخدمان خدمات جهازك.","Что приложение не делает.":"ما لا يفعله التطبيق.","Не следит за перемещениями, не продаёт и не показывает рекламу, не ставит диагнозов. Счётчики использования считаются только на этом устройстве.":"لا يتتبع تنقلاتك ولا يبيع البيانات ولا يعرض إعلانات ولا يشخّص. تبقى عدادات الاستخدام على هذا الجهاز فقط.","Важно.":"مهم.","Приложение не является медицинским изделием и не заменяет помощь специалиста. Это прототип, и тексты ещё не проверены психологом.":"التطبيق ليس جهازًا طبيًا ولا يغني عن مساعدة مختص. إنه نموذج أولي، ولم يراجع أخصائي نفسي النصوص بعد.","Показать вводную ещё раз":"اعرض المقدمة مجددًا","Если сейчас очень тяжело или есть риск навредить себе, позвони по номеру 112 или обратись к близкому человеку.":"إذا كان الأمر صعبًا جدًا الآن أو هناك خطر أن تؤذي نفسك، اتصل برقم الطوارئ المحلي أو تواصل مع شخص قريب.","Дневник":"اليوميات","Закрыть":"إغلاق","Маленький шаг":"خطوة صغيرة","Практика после трудного разговора":"تمرين بعد محادثة صعبة","Прежде чем начать":"قبل أن تبدأ","Коротко о том, как устроено «Рядом».":"باختصار، كيف يعمل Ryadom.","Что это":"ما هو","Цифровой помощник для разговора о состоянии, тренировки трудных разговоров и подбора мест. Это не врач и не психолог, диагнозов не ставит и не заменяет специалиста.":"مساعد رقمي للحديث عن حالتك، والتدرّب على المحادثات الصعبة، والعثور على أماكن. ليس طبيبًا ولا أخصائيًا نفسيًا، ولا يشخّص ولا يغني عن مختص.","Где данные":"أين بياناتك","Дневник, разговоры и «Обо мне» хранятся только на этом устройстве. Ты можешь выгрузить их или удалить всё в разделе «Обо мне».":"تُحفَظ اليوميات والمحادثات و«عنّي» على هذا الجهاز فقط. يمكنك تصديرها أو حذف كل شيء من قسم «عنّي».","Что уходит наружу":"ما يُرسَل إلى الخارج","Поиск мест отправляет запрос карте (OpenStreetMap). Если подключён режим с сервером и ИИ, текст сообщения уходит на сервер для ответа. Голосовой ввод использует службы твоего устройства.":"يرسل البحث عن الأماكن طلبك إلى خدمة خرائط (OpenStreetMap). إذا كان وضع الخادم والذكاء الاصطناعي مفعّلًا، يُرسَل نص الرسالة إلى الخادم للرد. الإدخال الصوتي يستخدم خدمات جهازك.","Если тяжело всерьёз":"إن كان الأمر صعبًا جدًا","При мыслях о вреде себе или другим обратись к человеку рядом или по номеру 112. Приложение подскажет, но срочную помощь оно не заменит.":"إن راودتك أفكار بإيذاء نفسك أو غيرك، تواصل مع شخص قريب منك أو اتصل برقم الطوارئ المحلي. يمكن للتطبيق أن يرشدك، لكنه لا يغني عن المساعدة العاجلة.","Понятно, продолжить":"فهمت، تابع","Рядом — маленькие шаги к себе":"Ryadom — خطوات صغيرة نحو ذاتك","Тревожно":"قلق","Сегодняшняя отметка сохранена. Её можно изменить.":"تم حفظ تسجيل اليوم. يمكنك تعديله.","дней с отметкой 3–4 из 4":"أيام بعلامة 3–4 من 4","Добавить в любимые":"أضف إلى المفضلة","Любимое место":"مكان مفضل","Изменить":"تعديل","Удалить":"حذف","Разговоры за этот день":"محادثات هذا اليوم","Удалить разговоры за этот день":"احذف محادثات هذا اليوم","Из «Обо мне»:":"من «عنّي»:","добавлено мной":"أضفته بنفسي","из разговора":"من المحادثة","Отметки состояния":"تسجيلات الحالة","Отметка о вводном экране":"تمت مشاهدة شاشة المقدمة","Разговоры":"المحادثات","Дневник настроения":"يوميات المزاج","Посещённые места":"الأماكن التي زرتها","Профиль «Обо мне»":"ملف «عنّي»","Меньше новостей":"أخبار أقل","Если поток новостей усиливает тревогу, отложи его на 15 минут и выбери конкретное время для проверки.":"إذا كان سيل الأخبار يزيد القلق، ضعه جانبًا 15 دقيقة واختر وقتًا محددًا للاطلاع.","Кому можно написать":"لمن يمكنك أن تكتب","Выбери человека, которому можно коротко написать: «Мне тревожно. Можешь побыть на связи?»":"اختر شخصًا يمكنك أن تكتب له باختصار: «أشعر بالقلق. هل يمكنك أن تبقى على تواصل قليلًا؟»","Назвать чувство":"سمِّ الشعور","Скажи себе: «Мне сейчас грустно». Не объясняй и не исправляй это чувство в ту же секунду.":"قل لنفسك: «أنا حزين الآن». لا تشرح الشعور ولا تصلحه في اللحظة نفسها.","Мягкий день":"يوم لطيف","Составь минимальный план: еда, вода, один обязательный шаг и один посильный источник тепла.":"ضع خطة بسيطة: طعام، ماء، خطوة ضرورية واحدة، ومصدر دفء واحد في متناولك.","Память о хорошем":"تذكّر شيء جيد","Вспомни один спокойный момент за последнюю неделю. Запиши детали: место, свет, звук.":"تذكّر لحظة هادئة واحدة من الأسبوع الماضي. اكتب التفاصيل: المكان، الضوء، الصوت.","Тёплый контакт":"تواصل دافئ","Напиши близкому человеку одну честную фразу о своём состоянии, если хочется быть услышанной или услышанным.":"اكتب لشخص قريب جملة صادقة واحدة عن حالك، إن رغبت أن يُسمَع صوتك.","Разрешить паузу":"اسمح لنفسك بالتوقف","Поставь таймер на пять минут. Можно просто посидеть, не превращая отдых в задачу.":"اضبط مؤقتًا لخمس دقائق. يمكنك أن تجلس فقط، دون أن تحوّل الراحة إلى مهمة.","Небольшая забота":"عناية صغيرة","Выбери одну бережную вещь: плед, душ, чай или прогулку. Отметь, стало ли хоть немного легче.":"اختر شيئًا لطيفًا واحدًا: بطانية، أو حمّام، أو شاي، أو نزهة. لاحظ إن أصبح الأمر أخفّ قليلًا.","Свет и воздух":"الضوء والهواء","Если удобно, подойди к окну или выйди на несколько минут. Заметь температуру воздуха и положение тела.":"إن أمكن، اقترب من النافذة أو اخرج لبضع دقائق. لاحظ حرارة الهواء ووضعية جسدك.","Прежде чем отвечать, отойди от переписки на пару минут. Спроси себя, какой результат нужен от ответа.":"قبل الرد، ابتعد عن المحادثة دقيقتين. اسأل نفسك: ما النتيجة التي تريدها من ردّك؟","Где злость в теле":"أين يسكن الغضب في جسدك","Заметь, где в теле сейчас напряжение. Расслабь челюсть или плечи, если это приятно, не подавляя чувство.":"لاحظ أين يوجد التوتر في جسدك الآن. أرخِ فكّك أو كتفيك إن كان ذلك مريحًا، دون كبت الشعور.","Черновик без отправки":"مسودة لن تُرسَل","Напиши резкий ответ в заметке, которую не отправишь. Затем выдели одну просьбу, которую действительно хочешь донести.":"اكتب الرد الحاد في ملاحظة لن ترسلها. ثم استخرج الطلب الوحيد الذي تريد إيصاله فعلًا.","Отойти от экрана":"ابتعد عن الشاشة","Положи телефон и сделай несколько шагов. Возвращайся к разговору, когда сможешь выбрать тон.":"ضع هاتفك جانبًا وامشِ بضع خطوات. عُد إلى المحادثة عندما تستطيع اختيار نبرتك.","Что задело":"ما الذي آلمك","Раздели на две строки: что произошло и какую важную потребность это затронуло.":"قسّمها إلى سطرين: ماذا حدث، وأي حاجة مهمة مسّها ذلك.","Безопасная разрядка":"تفريغ آمن","Сильно прижми стопы к полу на несколько секунд, затем отпусти. Повтори комфортно, без боли.":"اضغط بقدميك بقوة على الأرض لبضع ثوانٍ ثم أرخِهما. كرّر براحة ودون ألم.","Право отложить":"الحق في التأجيل","Если нет срочности, назначь время ответа позже. Тебе не обязательно решать конфликт в пике эмоций.":"إن لم يكن الأمر عاجلًا، حدّد وقتًا للرد لاحقًا. لست مضطرًا لحل الخلاف في ذروة المشاعر.","Одна задача":"مهمة واحدة","Выпиши всё, что давит. Обведи одну задачу, которую можно начать за десять минут.":"اكتب كل ما يثقل عليك. ضع دائرة حول مهمة واحدة يمكنك البدء بها في عشر دقائق.","Пять процентов":"خمسة بالمئة","Спроси: что сделает ближайший час на пять процентов легче? Выбери один маленький шаг.":"اسأل: ما الذي سيجعل الساعة القادمة أسهل بخمسة بالمئة؟ اختر خطوة صغيرة واحدة.","Снять лишнее":"تخلَّص من الزائد","Посмотри на список дел и вычеркни, перенеси или попроси помощи хотя бы с одним пунктом.":"انظر إلى قائمة مهامك واشطب أو أجّل أو اطلب المساعدة في بند واحد على الأقل.","Перерыв между делами":"استراحة بين المهام","Перед новой задачей сделай паузу: вода, взгляд вдаль, несколько спокойных движений.":"قبل مهمة جديدة خذ استراحة: ماء، ونظرة إلى البعيد، وبعض الحركات الهادئة.","Проверка тела":"فحص الجسد","Заметь голод, жажду, усталость и напряжение. Начни с самой простой телесной потребности.":"لاحظ الجوع والعطش والتعب والتوتر. ابدأ بأبسط حاجة جسدية.","Достаточно на сегодня":"يكفي لهذا اليوم","Сформулируй критерий «достаточно хорошо» для одной задачи. Остановись, когда он достигнут.":"حدّد معيار «جيد بما يكفي» لمهمة واحدة. توقّف عندما تبلغه.","Попросить ясности":"اطلب الوضوح","Если запрос размытый, уточни срок, приоритет и ожидаемый результат у того, кто его дал.":"إن كان الطلب غامضًا، استوضح الموعد والأولوية والنتيجة المتوقعة ممن طلبه.","Тихое окно":"نافذة هادئة","На десять минут отключи необязательные уведомления и займись одним делом.":"أوقف الإشعارات غير الضرورية لعشر دقائق وانشغل بأمر واحد.","За некоторое время до сна снизь яркость экрана и выбери спокойное занятие без цели «уснуть немедленно».":"قبل النوم بفترة، خفّف سطوع الشاشة واختر نشاطًا هادئًا دون هدف «النوم فورًا».","Запиши незавершённые дела и один следующий шаг к каждому. Вернуться к списку можно завтра.":"اكتب المهام غير المنتهية وخطوة تالية واحدة لكل منها. يمكنك العودة إلى القائمة غدًا.","Комфортная поза":"وضعية مريحة","Устрой тело удобнее и мягко замечай точки опоры. Дыхание оставь естественным.":"اجعل جسدك أكثر راحة ولاحظ بلطف نقاط الارتكاز. اترك تنفّسك طبيعيًا.","Тихие звуки":"أصوات هادئة","Прислушайся к трём звукам вокруг. Не оценивай их, просто отмечай появление и исчезновение.":"أنصت إلى ثلاثة أصوات من حولك. لا تحكم عليها، فقط لاحظ ظهورها واختفاءها.","Без борьбы со сном":"دون مقاومة النوم","Если не спится, напомни себе: отдых тоже ценен. Выбери спокойное занятие и вернись в постель, когда захочется.":"إن لم تستطع النوم، ذكّر نفسك بأن الراحة لها قيمة أيضًا. اختر نشاطًا هادئًا وعُد إلى السرير متى رغبت.","Назначь момент, после которого рабочие сообщения подождут до завтра, если это возможно.":"حدّد، إن أمكن، وقتًا تنتظر بعده رسائل العمل حتى الغد.","Мягкое завершение":"ختام لطيف","Назови одну вещь, которую удалось сделать сегодня. Даже очень маленькую.":"سمِّ شيئًا واحدًا نجحت في فعله اليوم، ولو كان صغيرًا جدًا.","Спокойное утро":"صباح هادئ","Подготовь одну мелочь для утра: одежду, стакан воды или список первого дела.":"حضّر شيئًا صغيرًا للصباح: ملابس، أو كوب ماء، أو ورقة بأول مهمة.","Составь фразу: «Когда произошло…, мне было… Мне хотелось бы…».":"كوّن جملة: «حين حدث…، شعرت بـ… وأودّ…».","Перескажи своими словами, что было услышано от другого человека, и уточни, верно ли это понято.":"أعد بكلماتك ما سمعته من الطرف الآخر، وتأكّد إن كان فهمك صحيحًا.","Попробуй короткий ответ без длинного оправдания: «Сейчас я не могу. Давай обсудим другой вариант».":"جرّب ردًا قصيرًا دون تبرير طويل: «لا أستطيع الآن. لنناقش خيارًا آخر».","Раздели лист: «за что отвечаю я» и «за что отвечает другой». Не бери на себя обе стороны.":"قسّم ورقة: «ما أنا مسؤول عنه» و«ما الآخر مسؤول عنه». لا تحمل الجانبين معًا.","Пауза в разговоре":"توقّف في المحادثة","Если разговор накаляется, предложи вернуться к нему в конкретное время после паузы.":"إذا احتدّت المحادثة، اقترح العودة إليها في وقت محدد بعد استراحة.","Запиши: как я хочу поддерживать контакт и что мне при этом важно решать самостоятельно.":"اكتب: كيف أريد الحفاظ على التواصل، وما الذي يهمني أن أقرّره بنفسي.","Один вопрос":"سؤال واحد","Вместо догадки спроси: «Что именно ты имеешь в виду?» Дай другому возможность прояснить слова.":"بدل التخمين، اسأل: «ماذا تقصد بالضبط؟» وامنح الآخر فرصة لتوضيح كلامه.","Если хочется контакта, отправь простое сообщение без ожидания немедленного ответа.":"إن رغبت في التواصل، أرسل رسالة بسيطة دون انتظار رد فوري.","После сложного разговора запиши конкретные задачи и договорённости отдельно от тона и эмоций.":"بعد محادثة صعبة، اكتب المهام والاتفاقات المحددة بمعزل عن النبرة والمشاعر.","Уточнить приоритет":"استوضح الأولوية","Спроси, какое из двух дел важнее сегодня. Это превращает неопределённость в выбор.":"اسأل أيّ المهمتين أهم اليوم. هكذا يتحوّل الغموض إلى اختيار.","Составь спокойный черновик: факт, уточняющий вопрос и срок, когда вернёшься с ответом.":"اكتب مسودة هادئة: الحقيقة، وسؤالًا للتوضيح، وموعد عودتك بالرد.","Раздели обратную связь на полезную часть, спорную часть и форму подачи. Возьми только то, что поможет задаче.":"قسّم الملاحظات إلى جزء مفيد، وجزء قابل للنقاش، وطريقة تقديم. خذ فقط ما يخدم المهمة.","Маленькая победа":"انتصار صغير","Запиши одно завершённое дело за день. Даже если другие ещё ждут.":"اكتب مهمة واحدة أنجزتها اليوم، حتى لو كانت غيرها ما زالت تنتظر.","Переход домой":"الانتقال إلى البيت","Закрой рабочий день короткой заметкой о первом шаге на завтра. Переключись на другую деятельность.":"اختم يوم العمل بملاحظة قصيرة عن أول خطوة غدًا. وانتقل إلى نشاط آخر.","Найти союзника":"ابحث عن حليف","Подумай, кто может помочь уточнить задачу, дать контекст или поддержать после трудного разговора.":"فكّر في من يمكنه المساعدة في توضيح المهمة أو إعطاء السياق أو دعمك بعد محادثة صعبة.","Вернуться к опоре, отделить событие от мыслей и выбрать свой следующий шаг.":"عُد إلى ما يسندك، وافصل الحدث عن الأفكار، واختر خطوتك التالية.","Проверь сон, еду, воду и паузы. Выбери самое доступное сейчас.":"تحقّق من النوم والطعام والماء والاستراحات. اختر الأسهل الآن.","Сократи задачу до действия на две минуты. Можно остановиться после него.":"قلّص المهمة إلى فعل يستغرق دقيقتين. يمكنك التوقف بعده.","Не объяснять усталость":"لا داعي لتبرير التعب","Скажи себе: «Сил мало, и я могу выбрать посильный темп». Определи один обязательный пункт.":"قل لنفسك: «طاقتي قليلة، ويمكنني اختيار وتيرة أقدر عليها». حدّد بندًا واحدًا ضروريًا.","Пауза без экрана":"استراحة بلا شاشة","На несколько минут убери экран и посмотри вдаль или закрой глаза, если комфортно.":"لبضع دقائق، أبعِد الشاشة وانظر إلى البعيد أو أغمض عينيك إن كان ذلك مريحًا.","Сформулируй конкретную небольшую просьбу человеку, который может помочь.":"صُغ طلبًا صغيرًا ومحددًا لشخص يستطيع المساعدة.","Список «потом»":"قائمة «لاحقًا»","Запиши необязательные дела в список на другой день, чтобы не держать их в голове.":"اكتب المهام غير الضرورية في قائمة ليوم آخر، كي لا تبقيها في رأسك.","Если есть силы и безопасно, пройди несколько минут в удобном темпе. Отдых тоже остаётся вариантом.":"إن كانت لديك طاقة وكان الأمر آمنًا، امشِ بضع دقائق بإيقاع مريح. الراحة تبقى خيارًا أيضًا.","Один приятный момент":"لحظة لطيفة واحدة","Выбери простую вещь, которая не требует подготовки: музыка, вода, окно или тёплый душ.":"اختر شيئًا بسيطًا لا يحتاج إلى تحضير: موسيقى، ماء، نافذة أو حمّام دافئ.","Мысль или факт":"فكرة أم حقيقة","Запиши тревожную мысль и рядом — факты за и против. Оставь место для неизвестного.":"اكتب الفكرة المقلقة، وبجانبها الحقائق المؤيدة والمعارضة. اترك مجالًا للمجهول.","Название мысли":"تسمية الفكرة","Когда мысль повторяется, произнеси: «У меня появилась мысль, что…». Это создаёт небольшую дистанцию.":"حين تتكرر فكرة، قل: «تراودني فكرة أنّ…». هذا يصنع مسافة صغيرة.","Круг влияния":"دائرة التأثير","Раздели ситуацию на то, что можешь изменить, на что можешь повлиять и что сейчас вне контроля.":"قسّم الموقف إلى ما يمكنك تغييره، وما يمكنك التأثير فيه، وما هو خارج سيطرتك الآن.","Один следующий шаг":"خطوة تالية واحدة","Вместо полного плана выбери действие, которое можно сделать сегодня.":"بدلًا من خطة كاملة، اختر فعلًا يمكنك القيام به اليوم.","Вернуться к ощущениям":"العودة إلى الحواس","Назови три звука, две видимые детали и одно ощущение от поверхности под рукой.":"سمِّ ثلاثة أصوات، وتفصيلين تراهما، وإحساسًا واحدًا من السطح تحت يدك.","Время для мысли":"وقت للفكرة","Если мысль возвращается, запиши её и назначь короткое время позже, когда сможешь к ней вернуться.":"إن عادت الفكرة، اكتبها وحدّد وقتًا قصيرًا لاحقًا لتعود إليها.","Два объяснения":"تفسيران","Найди ещё одно возможное объяснение событию, кроме самого пугающего. Не обязательно верить в него сразу.":"ابحث عن تفسير محتمل آخر لما حدث غير التفسير الأكثر إخافة. لا يلزم أن تصدّقه فورًا.","Спросить, а не угадать":"اسأل بدل أن تخمّن","Если мысль касается намерений другого, сформулируй вопрос, который поможет прояснить ситуацию.":"إن كانت الفكرة عن نوايا شخص آخر، صُغ سؤالًا يساعد على توضيح الموقف.","Что уже помогает":"ما يساعد بالفعل","Заметь, что сейчас поддерживает тебя: человек, место, движение или привычка. Сохрани это в памяти.":"لاحظ ما يسندك الآن: شخص، أو مكان، أو حركة، أو عادة. احتفظ بذلك في ذاكرتك.","Поблагодарить себя":"اشكر نفسك","Назови один свой шаг сегодня без оценки его масштаба.":"سمِّ خطوة واحدة قمت بها اليوم دون الحكم على حجمها.","Фото момента":"صورة اللحظة","Опиши словами спокойный момент: цвет, звук, температуру и чувство в теле.":"صِف بالكلمات لحظة هادئة: اللون، والصوت، والحرارة، والإحساس في جسدك.","Забота на завтра":"عناية للغد","Выбери одну маленькую вещь, которую хочется повторить завтра.":"اختر شيئًا صغيرًا ترغب في تكراره غدًا.","Делиться хорошим":"مشاركة الجيد","Если хочется, расскажи кому-то о приятном моменте, не превращая это в отчёт.":"إن رغبت، أخبر أحدًا عن لحظة لطيفة دون أن تحوّلها إلى تقرير.","Просто побыть":"فقط كُن","Разреши себе несколько минут ничего не улучшать. Замечай, что уже есть.":"اسمح لنفسك ببضع دقائق دون أن تحسّن أي شيء. لاحظ ما هو موجود بالفعل.","Мягкий план":"خطة لطيفة","Пока спокойно, запиши, что обычно помогает в более сложные дни.":"بينما أنت هادئ، اكتب ما يساعدك عادةً في الأيام الأصعب.","Свободное время":"وقت فراغ","Оставь в дне небольшой отрезок без обязательного результата.":"اترك في يومك فترة قصيرة بلا نتيجة مطلوبة.","2 минуты":"دقيقتان","Дыши комфортно, без задержки и усилия. На вдохе круг расширяется, на выдохе сужается. Если кружится голова, остановись и дыши обычно.":"تنفّس براحة، دون حبس أو إجهاد. يتسع الدائرة مع الشهيق ويضيق مع الزفير. إن شعرت بدوار، توقّف وتنفّس بشكل طبيعي.","Начать дыхание":"ابدأ التنفّس","Закончить":"إنهاء","Дыши в своём ритме":"تنفّس على إيقاعك","1 минута":"دقيقة واحدة","Назови 5 вещей, которые видишь; 4, которые ощущаешь телом; 3 звука. Не спеши. Сейчас ты здесь.":"سمِّ 5 أشياء تراها، و4 تشعر بها بجسدك، و3 أصوات. لا تستعجل. أنت هنا الآن.","Представь между собой и резкими словами прозрачное стекло. Слова остаются по ту сторону. Спроси себя: что из сказанного относится к задаче, а что говорит о состоянии другого человека?":"تخيّل زجاجًا شفافًا بينك وبين الكلمات القاسية. تبقى الكلمات على الجانب الآخر. اسأل نفسك: ما الذي يتعلّق بالمهمة مما قيل، وما الذي يعبّر عن حالة الشخص الآخر؟","3 минуты":"3 دقائق","Запиши три короткие строки: 1) Что произошло? 2) Что я сейчас чувствую? 3) Какой один небольшой шаг мне доступен? Не нужно искать идеальное решение.":"اكتب ثلاثة أسطر قصيرة: 1) ماذا حدث؟ 2) بماذا أشعر الآن؟ 3) ما الخطوة الصغيرة المتاحة لي؟ لا حاجة إلى حل مثالي.","Если бы близкий человек оказался на твоём месте, какие слова поддержки нашлись бы для него? Попробуй обратиться с этой же фразой к себе.":"لو كان شخص قريب منك في مكانك، أي كلمات دعم كنت ستقولها له؟ جرّب أن تقولها لنفسك.","Если есть возможность, встань, сделай несколько спокойных шагов и выпей воды. Посмотри в окно или выйди на воздух. Потом проверь, изменилось ли что-то хотя бы на один процент.":"إن أمكن، قف وامشِ بضع خطوات هادئة واشرب ماءً. انظر من النافذة أو اخرج للهواء. ثم تحقّق إن تغيّر شيء ولو بنسبة واحد بالمئة.","1 мин":"دقيقة","2 мин":"دقيقتان","3 мин":"3 دقائق","5 мин":"5 دقائق","10 мин":"10 دقائق","✦ РЯДОМ · ПРАКТИКА":"✦ RYADOM · تمرين","ПЕРЕД НАЧАЛОМ":"قبل البدء","Что осталось после разговора?":"ما الذي بقي بعد المحادثة؟","Нам не нужно сейчас разбирать всё сразу. Отметь, с кем был разговор и насколько сильно он задел тебя в данный момент.":"لسنا مضطرين لتفكيك كل شيء الآن. حدّد مع من كانت المحادثة وإلى أي حد آلمتك في هذه اللحظة.","На работе":"في العمل","С близким":"مع شخص قريب","В другой ситуации":"في موقف آخر","Насколько сильно задело сейчас?":"إلى أي حد يؤلمك الآن؟","Немного":"قليلًا","Очень сильно":"كثيرًا جدًا","Если сейчас небезопасно или ситуация продолжается, сначала позаботься о своей безопасности и обратись к человеку рядом. Практику можно закрыть в любой момент.":"إن لم تكن بأمان الآن أو كان الموقف مستمرًا، اهتم بسلامتك أولًا وتواصل مع شخص قريب. يمكنك إغلاق التمرين في أي وقت.","Начать →":"ابدأ ←","01 · ВЕРНУТЬСЯ В МОМЕНТ":"01 · العودة إلى اللحظة","Сейчас ты здесь":"أنت هنا الآن","Не нужно менять дыхание. Найди глазами одну вещь вокруг, услышь один звук и почувствуй опору под ногами или телом. Нажми на то, что удалось заметить.":"لا حاجة إلى تغيير تنفّسك. ابحث بعينيك عن شيء واحد حولك، واسمع صوتًا واحدًا، واشعر بما يسندك تحت قدميك أو جسدك. اضغط على ما استطعت ملاحظته.","здесь":"هنا","и сейчас":"والآن","○ Вижу предмет":"○ أرى شيئًا","○ Слышу звук":"○ أسمع صوتًا","○ Чувствую опору":"○ أشعر بما يسندني","Можно просто прочитать и двигаться дальше. Если внимание к телу неприятно, пропусти этот шаг.":"يمكنك أن تقرأ فقط وتتابع. إن كان الانتباه إلى الجسد مزعجًا، تخطَّ هذه الخطوة.","Назад":"رجوع","Продолжить →":"متابعة ←","✓ Вижу предмет":"✓ أرى شيئًا","✓ Слышу звук":"✓ أسمع صوتًا","✓ Чувствую опору":"✓ أشعر بما يسندني","02 · ОТДЕЛИТЬ СОБЫТИЕ ОТ МЫСЛИ":"02 · افصل الحدث عن الفكرة","Две разные вещи":"شيئان مختلفان","Попробуй разделить то, что произошло, и то, что подумалось после. Это не проверка правильности твоих чувств. Поля можно оставить пустыми.":"حاول أن تفصل ما حدث عمّا فكّرت فيه بعده. هذا ليس اختبارًا لصحة مشاعرك. يمكنك ترك الحقول فارغة.","Что было сказано или сделано?":"ما الذي قيل أو فُعل؟","Какая мысль у меня об этом появилась?":"ما الفكرة التي راودتني عن ذلك؟","Чувства реальны. Мысль о себе — не всегда факт. Необязательно находить объяснение прямо сейчас.":"المشاعر حقيقية. الفكرة عن نفسك ليست دائمًا حقيقة. لا يلزم أن تجد تفسيرًا الآن.","03 · ОДИН СЛЕДУЮЩИЙ ШАГ":"03 · خطوة تالية واحدة","Что сейчас подойдёт?":"ما الذي يناسب الآن؟","Выбери действие, которое зависит от тебя. Оно может быть маленьким и не обязано решать весь конфликт.":"اختر فعلًا يعتمد عليك. يمكن أن يكون صغيرًا ولا يجب أن يحل الخلاف كله.","Дать себе паузу":"امنح نفسك وقفة","Можно ничего не отправлять прямо сейчас. Назначь момент, когда снова посмотришь на ситуацию.":"لا يلزم أن ترسل شيئًا الآن. حدّد لحظة تعود فيها للنظر في الموقف.","Уточнить задачу":"استوضح المهمة","Этот вариант подходит, если за неприятным тоном была конкретная рабочая задача.":"يناسب هذا الخيار إن كانت وراء النبرة المزعجة مهمة عمل محددة.","Обозначить границу":"ضع حدًا","Подстрой слова под себя. Ты выбираешь время и безопасный способ разговора.":"عدّل الكلمات بما يناسبك. أنت من يختار الوقت والطريقة الآمنة للحديث.","Попросить поддержки":"اطلب الدعم","Поддержка может быть короткой: сообщение, звонок или совместная прогулка.":"يمكن أن يكون الدعم قصيرًا: رسالة، أو مكالمة، أو نزهة معًا.","Как сейчас, по той же шкале?":"كيف هو الآن، على المقياس نفسه؟","Не хочу оценивать":"لا أريد التقييم","Завершить и сохранить →":"إنهاء وحفظ ←","ВОЗМОЖНАЯ ФРАЗА":"عبارة ممكنة","«Я вернусь к разговору позже. Сейчас мне нужно немного времени».":"«سأعود إلى الحديث لاحقًا. أحتاج الآن إلى بعض الوقت».","Готово":"تم","ТВОЙ МАЛЕНЬКИЙ ШАГ":"خطوتك الصغيرة","Можно остановиться здесь":"يمكنك التوقف هنا","Состояние замечено, действие выбрано. Не нужно заставлять себя чувствовать лучше.":"لاحظتَ حالتك واخترتَ فعلًا. لا حاجة إلى إجبار نفسك على الشعور بتحسّن.","ЧТО ВЫБРАНО":"ما الذي اخترته","Состояние пока не изменилось. Ты всё равно можешь остановиться или выбрать поддержку.":"لم تتغيّر حالتك بعد. ما زال بإمكانك التوقف أو اختيار الدعم.","В дневник сохранены только тема, выбранный шаг и твоя оценка результата. Написанные тобой фразы не сохранялись.":"حُفِظ في اليوميات الموضوع والخطوة المختارة وتقييمك فقط. لم تُحفَظ العبارات التي كتبتها.","Вернуться в приложение":"العودة إلى التطبيق","Добавить место":"أضف مكانًا","Название *":"الاسم *","Например, любимая кофейня":"مثلًا، مقهاك المفضل","Район или адрес":"الحي أو العنوان","Необязательно":"اختياري","Примерное время":"الوقت التقريبي","Что это за место?":"ما نوع المكان؟","Кафе":"مقهى","Парк":"حديقة","Прогулка":"نزهة","Культура":"ثقافة","Другое":"أخرى","Как тебе там было?":"كيف كان شعورك هناك؟","Спокойно":"هادئ","Радостно":"فرِح","Уютно":"مريح","Грустно":"حزين","По-разному":"متفاوت","Что запомнилось?":"ما الذي بقي في ذاكرتك؟","Отмена":"إلغاء","Сохранить место":"احفظ المكان","Удалить разговоры, отметки, места и любимые места из дневника на этом устройстве? Игровой прогресс останется.":"حذف المحادثات والتسجيلات والأماكن والمفضلة من اليوميات على هذا الجهاز؟ سيبقى تقدّم الألعاب.","{x}: {0}":"{x}: {0}","Сообщений в разговоре":"رسائل في المحادثة","Практик открыто":"تمارين مفتوحة","Тренажёров начато":"تدريبات بدأتها","Тренажёров пройдено":"تدريبات أكملتها","Открытий «Практик»":"فتح «التمارين»","Открытий «Игр»":"فتح «الألعاب»","Открытий «Мест»":"فتح «الأماكن»","Открытий дневника":"فتح اليوميات","{x}: {y} {0} из {1}":"{x}: {y} {0} من {1}","тревога":"القلق","грусть":"الحزن","беспокойство":"التوتر","спокойствие":"الهدوء","Да, удалить":"نعم، احذف","Неспешная прогулка, книга или чашка чая. Выбирай только то, на что есть силы.":"نزهة هادئة أو كتاب أو كوب شاي. اختر فقط ما لديك طاقة له.","Место, где можно сменить обстановку. Тишину и отсутствие людей лучше проверить самому.":"مكان لتغيير الأجواء. تحقق بنفسك من الهدوء وقلة الناس.","Прогулка, вид на город или уютное место для встречи.":"نزهة أو إطلالة على المدينة أو مكان دافئ للقاء.","Места, где можно гулять, смотреть кино или быть среди людей.":"أماكن للمشي أو مشاهدة فيلم أو التواجد بين الناس.","Пространства для неторопливого времени.":"أماكن لوقت بلا عجلة.","Музей, галерея или книжное место могут дать новую мысль.":"قد يمنحك متحف أو معرض أو مكتبة فكرة جديدة.","Поблизости и без большого плана: кофе или короткая прогулка.":"قريب ومن دون خطة كبيرة: قهوة أو نزهة قصيرة.","Места для встречи. Загруженность и атмосферу уточни перед поездкой.":"أماكن للقاء. تحقق من الازدحام والأجواء قبل الذهاب.","Будут удалены дневник, разговоры, «Обо мне», места и прогресс игр на этом устройстве. Вернуть их будет нельзя, если нет копии.":"ستُحذف اليوميات والمحادثات و«عني» والأماكن وتقدم الألعاب على هذا الجهاز. لا يمكن استعادتها من دون نسخة احتياطية.","Да, удалить всё":"نعم، احذف كل شيء","Удалить все записи профиля? Вернуть их будет нельзя.":"حذف كل إدخالات الملف الشخصي؟ لا يمكن استعادتها.","Да, стереть":"نعم، امسح","После нескольких отметок здесь появится короткое наблюдение о твоём состоянии.":"بعد بضعة تسجيلات ستظهر هنا ملاحظة قصيرة عن حالتك.","Здесь появятся твои отметки после первого разговора.":"ستظهر تسجيلاتك هنا بعد أول محادثة.","Разговор с «Рядом»":"محادثة مع Ryadom","Например: трудный разговор, прогулка или приятный момент":"مثلاً: محادثة صعبة أو نزهة أو لحظة لطيفة","Интерактивный прототип приложения ежедневной эмоциональной поддержки.":"نموذج تفاعلي لتطبيق دعم عاطفي يومي.","Твои мысли остаются только на этом экране и не сохраняются":"تبقى أفكارك على هذه الشاشة فقط ولا تُحفظ","Заметка":"ملاحظة","Как ты сейчас после этого шага?":"كيف حالك الآن بعد هذه الخطوة؟","Чуть легче":"أخف قليلاً","Пока так же":"كما هو حتى الآن","Стало хуже":"ساءت الحال","День":"يوم","Отмечено состояний: {0}. График показывает только твои ответы, без оценок и диагнозов.":"الحالات المسجلة: {0}. يعرض الرسم إجاباتك فقط، دون تقييمات أو تشخيصات.","Одна короткая отметка в день — уже начало.":"تسجيل قصير واحد في اليوم بداية جيدة.","Удалить все отметки из этого браузера?":"حذف كل التسجيلات من هذا المتصفح؟","В {0} из {1} отмеченных дней тревога была сильной. Можно посмотреть, что происходило в эти дни, и обратиться за поддержкой, если это мешает жить.":"في {0} من {1} يوماً مسجلاً كان القلق شديداً. يمكنك النظر فيما حدث في تلك الأيام وطلب الدعم إن كان ذلك يعيق حياتك.","За выбранный период сильная тревога отмечалась в {0} из {1} дней. Посмотри, какие занятия и разговоры помогали тебе чувствовать себя спокойнее.":"خلال الفترة المختارة سُجل قلق شديد في {0} من {1} يوماً. انظر أي أنشطة ومحادثات ساعدتك على الشعور بهدوء أكبر.","На этот день нет записи. Пустая клетка ничего не говорит о том, каким был день.":"لا يوجد تسجيل لهذا اليوم. الخانة الفارغة لا تقول شيئاً عن يومك.","чуть легче":"أخف قليلاً","без изменений":"دون تغيير","стало хуже":"ساءت","без оценки":"دون تقييم","Удалить разговоры, отметки и заметки дневника из этого браузера? Игровой прогресс останется.":"حذف المحادثات والتسجيلات وملاحظات اليوميات من هذا المتصفح؟ سيبقى تقدم الألعاب.","Скоро":"قريباً","Ничего не найдено. Попробуй другое слово или состояние.":"لم يُعثر على شيء. جرّب كلمة أو حالة أخرى.","Поддержка":"الدعم","Мне очень жаль, что сейчас так тяжело. Если есть риск причинить себе вред прямо сейчас, позови человека рядом и обратись за срочной помощью по местному экстренному номеру. Ты можешь сказать: «Мне сейчас небезопасно оставаться одной или одному. Побудь со мной и помоги получить помощь».":"أنا آسف جداً لأن الأمر صعب إلى هذا الحد الآن. إن كان هناك خطر أن تؤذي نفسك الآن، فاستدعِ شخصاً قريباً واطلب مساعدة عاجلة عبر رقم الطوارئ المحلي. يمكنك أن تقول: «ليس من الآمن أن أبقى وحدي الآن. ابقَ معي وساعدني في الحصول على المساعدة».","Показать фразу для близкого":"اعرض رسالة لشخص قريب","Можно отправить: «Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь со мной. Помоги обратиться за помощью».":"يمكنك أن ترسل: «أمرّ بوقت صعب جداً الآن. أرجوك اتصل بي أو ابقَ معي. ساعدني لأطلب المساعدة».","Хорошо, что об этом сказано вслух. Если состояние изменится, обратись к человеку рядом или за срочной помощью.":"من الجيد أنك قلت ذلك. إن تغيّرت حالتك، فتوجّه إلى شخص قريب أو اطلب مساعدة عاجلة.","Начнём новый разговор. Как ты сейчас?":"لنبدأ محادثة جديدة. كيف حالك الآن؟","Рада это слышать. Что сегодня помогло тебе чувствовать себя так?":"يسعدني سماع ذلك. ما الذي ساعدك على الشعور هكذا اليوم؟","Спасибо, что об этом сказано. Что произошло или когда это ощущение появилось? Можно ответить своими словами.":"شكراً لأنك قلت ذلك. ماذا حدث أو متى ظهر هذا الشعور؟ يمكنك الإجابة بكلماتك.","Близкие":"الأحبة","Не знаю, почему":"لا أعرف لماذا","Понимаю. Насколько сильно это сейчас ощущается — от 1 до 4? Если сложно оценить, можно пропустить.":"أفهم. ما مدى قوة هذا الشعور الآن، من 1 إلى 4؟ إن كان التقييم صعباً يمكنك التخطي.","1 · немного":"1 · قليلاً","2 · заметно":"2 · بشكل ملحوظ","3 · сильно":"3 · بشدة","4 · очень сильно":"4 · بشدة كبيرة","Пропустить":"تخطٍّ","Что хочется сделать с этим ощущением?":"ماذا تود أن تفعل بهذا الشعور؟","Что сейчас было бы нужнее: немного успокоиться, разобраться в ситуации, просто выговориться или отдохнуть?":"ما الذي تحتاجه أكثر الآن: أن تهدأ قليلاً، أو تفهم الموقف، أو تفضفض فقط، أو ترتاح؟","Успокоиться":"أن أهدأ","Разобраться":"أن أفهم","Выговориться":"أن أفضفض","Отдохнуть":"أن أرتاح","Я слушаю. Расскажи, что было самым неприятным или важным в этом моменте.":"أنا أستمع. أخبرني ما كان الأكثر إزعاجاً أو أهمية في تلك اللحظة.","Похоже, это действительно задело. Что хотелось бы получить сейчас? Можно выбрать маленький шаг, а можно продолжить разговор.":"يبدو أن هذا آلمك حقاً. ماذا تود الآن؟ يمكنك اختيار خطوة صغيرة أو متابعة الحديث.","Рассказать ещё":"أن أحكي المزيد","Закончить пока":"التوقف الآن","Я рядом. Что ещё важно сказать?":"أنا هنا. ما الذي يهم أن تقوله أيضاً؟","Спасибо, что поделилась или поделился. Можно вернуться, когда захочешь.":"شكراً لمشاركتك. يمكنك العودة متى شئت.","Новый разговор":"محادثة جديدة","Я слушаю. Что хочется рассказать?":"أنا أستمع. ماذا تود أن تحكي؟","Спасибо за разговор. Вернись, когда захочешь.":"شكراً على المحادثة. عد متى شئت.","Слышу тебя. Что из этого сейчас важнее всего? Можешь рассказать ещё или выбрать шаг.":"أسمعك. ما الأهم في هذا الآن؟ يمكنك أن تحكي المزيد أو تختار خطوة.","Рада, что стало хоть немного легче. Что именно помогло?":"يسعدني أن الأمر خفّ قليلاً. ما الذي ساعد بالضبط؟","Жаль, что стало хуже. Остановимся с этой практикой. Сейчас лучше выбрать более мягкую поддержку или обратиться к близкому человеку.":"آسف لأن الأمر ساء. لنتوقف عن هذا التمرين. من الأفضل الآن اختيار دعم ألطف أو التواصل مع شخص قريب.","Хорошо, что это получилось заметить. Можно попробовать другой шаг или просто остановиться.":"من الجيد أنك لاحظت ذلك. يمكنك تجربة خطوة أخرى أو التوقف ببساطة.","Расскажу ещё":"سأحكي المزيد","Я слушаю. Что сейчас на первом плане?":"أنا أستمع. ما الذي يشغلك أكثر الآن؟","Спасибо за разговор. Береги свой темп.":"شكراً على المحادثة. حافظ على وتيرتك.","Если захочешь, начнём новый разговор.":"إن أردت، نبدأ محادثة جديدة.","Тогда начнём с очень маленькой паузы.":"إذن لنبدأ باستراحة صغيرة جداً.","Давай отделим то, что произошло, от догадок.":"لنفصل ما حدث عن التخمينات.","Можно попробовать один из этих шагов. Выбирай только то, что подходит.":"يمكنك تجربة إحدى هذه الخطوات. اختر فقط ما يناسبك.","Хочу рассказать ещё":"أريد أن أحكي المزيد","Пока достаточно":"يكفي الآن","Как ты после этого шага?":"كيف حالك بعد هذه الخطوة؟","Голосовой ввод не поддерживается этим браузером":"هذا المتصفح لا يدعم الإدخال الصوتي","Голосовой ввод недоступен в этом браузере. Можно писать текстом.":"الإدخال الصوتي غير متاح في هذا المتصفح. يمكنك الكتابة.","Распознавание голоса выполняет устройство и может передавать запись его сервису. Продолжить?":"يتولى جهازك التعرف على الصوت وقد يرسل التسجيل إلى خدمته. هل تتابع؟","Да, включить":"نعم، شغّل","Остановить запись":"إيقاف التسجيل","Слушаю. Фраза появится в поле ввода — проверь её перед отправкой.":"أستمع. ستظهر العبارة في حقل الإدخال — راجعها قبل الإرسال.","Проверь текст и нажми отправить, когда текст устроит.":"راجع النص واضغط إرسال عندما يناسبك.","Нет доступа к микрофону. Можно продолжить текстом.":"لا يوجد وصول إلى الميكروفون. يمكنك المتابعة بالكتابة.","Не удалось распознать речь. Попробуй ещё раз или напиши текстом.":"تعذّر التعرف على الكلام. حاول مجدداً أو اكتب.","Не удалось включить микрофон.":"تعذّر تشغيل الميكروفون.","4–6 минут":"4–6 دقائق","Небольшая самостоятельная практика после неприятного разговора.":"تمرين قصير تقوم به بنفسك بعد محادثة مزعجة.","После трудного разговора · 4–6 минут":"بعد محادثة صعبة · 4–6 دقائق","«Помоги понять: какой результат ожидается и к какому сроку?»":"«ساعدني لأفهم: ما النتيجة المتوقعة وفي أي موعد؟»","«Мне важно обсудить вопрос, когда мы можем говорить спокойно».":"«من المهم لي أن نناقش هذا عندما نستطيع التحدث بهدوء».","«У меня был трудный разговор. Можешь немного побыть со мной на связи?»":"«مررت بمحادثة صعبة. هل يمكنك أن تبقى على تواصل معي قليلاً؟»","Шаг {0} из 4":"الخطوة {0} من 4","Пауза":"توقف","Результат не оценён. Это тоже нормально.":"لم يُقيَّم الناتج. وهذا طبيعي أيضاً.","Отмечено небольшое облегчение.":"سُجّل ارتياح بسيط.","Стало тяжелее. Эту практику можно оставить и обратиться к человеку, которому доверяешь.":"أصبح الأمر أصعب. يمكنك ترك هذا التمرين والتوجه إلى شخص تثق به.","Вижу предмет":"أرى شيئاً","Слышу звук":"أسمع صوتاً","Чувствую опору":"أشعر بسند","Например: «Руководитель повысил голос и попросил переделать отчёт»":"مثلاً: «رفع المدير صوته وطلب إعادة التقرير»","Например: «Наверное, я ни на что не способна или не способен»":"مثلاً: «ربما لا أستطيع فعل أي شيء»","Практика пройдена в твоём темпе. Хочешь рассказать ещё или закончить?":"أُنجز التمرين بوتيرتك. هل تود أن تحكي المزيد أم تنهي؟","Отмечено, что стало немного легче. Хочешь остановиться или рассказать, какой шаг оказался выбран?":"سُجّل أن الأمر خفّ قليلاً. هل تود التوقف أم أن تخبرني أي خطوة اخترت؟","Похоже, сейчас стало тяжелее. Остановимся. Можно обратиться к человеку рядом или выбрать другую поддержку.":"يبدو أن الأمر أصبح أصعب. لنتوقف. يمكنك التوجه إلى شخص قريب أو اختيار دعم آخر.","Спасибо за оценку результата. Хочешь рассказать ещё или закончить?":"شكراً لتقييم النتيجة. هل تود أن تحكي المزيد أم تنهي؟","тревожно":"قلق","тяжело":"ثقيل","злюсь":"غاضب","нормально":"عادي","хорошо":"جيد","✓ Сделано":"✓ تم","Скопировано":"تم النسخ","Не удалось":"تعذّر ذلك","Запись о тебе сейчас выключена. Включить её можно в разделе «Обо мне».":"الملاحظات عنك متوقفة الآن. يمكنك تفعيلها في «عني».","Такая запись уже есть или список полон.":"هذا الإدخال موجود بالفعل أو القائمة ممتلئة.","Избранные места":"الأماكن المفضلة","Найденные места":"الأماكن التي عُثر عليها","Выбранный город":"المدينة المختارة","Счётчики на этом устройстве":"العدادات على هذا الجهاز","Цепочки практик":"سلاسل التمارين","Согласие на голос":"الموافقة على الصوت","Настройка озвучки":"إعدادات القراءة الصوتية","Прогресс игр":"تقدم الألعاب","Прогресс историй":"تقدم القصص","Прогресс квестов":"تقدم المهام","Не удалось прочитать: это не файл данных «Рядом».":"تعذّرت القراءة: هذا ليس ملف بيانات Ryadom.","Это не файл данных «Рядом».":"هذا ليس ملف بيانات Ryadom.","В файле нет данных для восстановления.":"لا يحتوي الملف على بيانات للاستعادة.","Пока ничего не сохранено":"لم يُحفظ شيء بعد","Данные для переноса":"بيانات النقل","Выбери, куда сохранить: «Файлы», облако, почта или мессенджер себе.":"اختر مكان الحفظ: «الملفات» أو السحابة أو البريد أو تطبيق مراسلة إلى نفسك.","Не получилось открыть «Поделиться». Воспользуйся кнопкой «Скопировать текст».":"تعذّر فتح «مشاركة». استخدم زر «نسخ النص».","Файл сохраняется. Если ничего не произошло — воспользуйся кнопкой «Скопировать текст».":"جارٍ حفظ الملف. إن لم يحدث شيء، استخدم زر «نسخ النص».","Не получилось сохранить файл. Воспользуйся кнопкой «Скопировать текст».":"تعذّر حفظ الملف. استخدم زر «نسخ النص».","Скопировано. Вставь в заметки или сообщение себе.":"تم النسخ. الصقه في الملاحظات أو في رسالة إلى نفسك.","Скопировать автоматически не вышло. Текст выделен — скопируй его вручную.":"تعذّر النسخ تلقائياً. النص محدد — انسخه يدوياً.","Файл слишком большой.":"الملف كبير جداً.","Вставь сюда скопированный текст и нажми кнопку ещё раз":"الصق النص المنسوخ هنا واضغط الزر مرة أخرى","Всё удалено. Обновляю приложение…":"حُذف كل شيء. جارٍ تحديث التطبيق…","Где хранятся":"أين تُخزَّن","Что передаётся наружу":"ما الذي يُرسَل إلى الخارج","Что приложение не делает":"ما لا يفعله التطبيق","Важно":"مهم","Новых мест для добавления нет. Отметь любимые в разделе «Места» или посещения в дневнике.":"لا توجد أماكن جديدة لإضافتها. علّم المفضلة في «الأماكن» أو الزيارات في اليوميات.","Сейчас записи не используются: ни в разговоре, ни в подсказках, ни на сервере.":"الملاحظات غير مستخدمة الآن: لا في المحادثة ولا في الاقتراحات ولا على الخادم.","Романтично":"رومانسي","Весело":"ممتع","Хочется нового":"أريد شيئاً جديداً","Устало":"متعب","Хочется общения":"أريد صحبة","Расстояние неизвестно":"المسافة غير معروفة","Сад":"حديقة","Библиотека":"مكتبة عامة","Музей":"متحف","Смотровая площадка":"منصة مشاهدة","Ресторан":"مطعم","Галерея":"معرض فني","Кинотеатр":"سينما","Театр":"مسرح","Достопримечательность":"معلم سياحي","Арт-пространство":"مساحة فنية","Книжный магазин":"مكتبة لبيع الكتب","Бар":"حانة","Уже есть в твоём дневнике":"موجود بالفعل في يومياتك","Отметок об этом месте в дневнике: {0}":"إدخالات هذا المكان في اليوميات: {0}","Любимое место · под выбранное настроение может подойти другое":"مكان مفضل · قد يناسب المزاج المختار مكان آخر","На карте ↗":"على الخريطة ↗","Была/был здесь":"كنت هنا","01 / ТВОИ МЕСТА":"01 / أماكنك","Любимые сначала":"المفضلة أولاً","02 / ПОБЛИЗОСТИ":"02 / بالقرب منك","Новые места рядом":"أماكن جديدة قريبة","Показано {0} мест рядом с «{1}».":"عُرض {0} مكاناً بالقرب من «{1}».","Найдено {0} мест в радиусе около 2 км. Данные OpenStreetMap могут быть неполными.":"عُثر على {0} مكاناً في نطاق نحو 2 كم. قد تكون بيانات OpenStreetMap غير مكتملة.","Поблизости пока не нашлось мест под это настроение. Попробуй другой район или настроение.":"لم نجد بعد أماكن قريبة لهذا المزاج. جرّب منطقة أو مزاجاً آخر.","Поиск новых мест сейчас недоступен. Любимые места из дневника остаются здесь. Попробуй позже или укажи другой район.":"البحث عن أماكن جديدة غير متاح الآن. تبقى الأماكن المفضلة من اليوميات هنا. حاول لاحقاً أو اختر منطقة أخرى.","Этот браузер не поддерживает определение местоположения. Введи город вручную.":"هذا المتصفح لا يدعم تحديد الموقع. أدخل المدينة يدوياً.","Запрашиваем местоположение…":"جارٍ طلب الموقع…","текущей точки":"الموقع الحالي","Не удалось получить местоположение. Введи город или район вручную.":"تعذّر الحصول على الموقع. أدخل مدينة أو منطقة يدوياً.","Не удалось найти этот город или район. Попробуй уточнить название.":"تعذّر العثور على هذه المدينة أو المنطقة. جرّب اسماً أدق.","Не удалось найти город сейчас. Попробуй ещё раз позже или используй геолокацию.":"تعذّر العثور على المدينة الآن. حاول لاحقاً أو استخدم تحديد الموقع.","Убрать из любимых":"إزالة من المفضلة","Изменить место":"تغيير المكان","Или выбери любимое:":"أو اختر من المفضلة:","Ты":"أنت","МЕНЮ":"القائمة","Попробовать ещё раз":"حاول مجدداً","Дальше →":"التالي →","Скопировать":"نسخ","Сначала напиши свою версию.":"اكتب نسختك أولاً.","Скопировано.":"تم النسخ.","Скопируй текст вручную.":"انسخ النص يدوياً.","Запомнить в «Обо мне»":"احفظ في «عني»","Записано в «Обо мне».":"حُفظ في «عني».","К играм":"إلى الألعاب","Озвучка ответов включена":"قراءة الردود بصوت عالٍ مفعّلة","Озвучка включена.":"القراءة الصوتية مفعّلة.","Данные «Рядом»":"بيانات Ryadom","Копия данных приложения «Рядом». Храни её в надёжном месте.":"نسخة من بيانات تطبيق Ryadom. احفظها في مكان آمن.","Сохранить копию":"حفظ نسخة","Как ты сегодня? Можно отметить состояние за минуту.":"كيف حالك اليوم؟ يمكنك تسجيل حالتك في دقيقة.","Минутка для себя: как прошёл день?":"دقيقة لنفسك: كيف كان يومك؟","Если день был непростым — я рядом. Можно просто отметить настроение.":"إن كان اليوم صعباً فأنا هنا. يمكنك فقط تسجيل مزاجك.","Напоминания недоступны на этом устройстве.":"التذكيرات غير متاحة على هذا الجهاز.","Напоминание выключено.":"تم إيقاف التذكير.","Уведомления запрещены. Их можно разрешить в настройках телефона для приложения «Рядом».":"الإشعارات محظورة. يمكنك السماح بها من إعدادات الهاتف لتطبيق Ryadom.","Напоминание":"تذكير","Раз в день мягко напомню отметить состояние. Работает без интернета, ничего никуда не отправляется.":"مرة في اليوم سأذكّرك بلطف بتسجيل حالتك. يعمل دون إنترنت ولا يُرسل أي شيء.","Ежедневное напоминание":"تذكير يومي","Каждый день":"كل يوم","Время напоминания":"وقت التذكير","Похоже, сейчас тревожно.":"يبدو أنك قلق الآن.","Похоже, сейчас грустно.":"يبدو أنك حزين الآن.","Похоже, сейчас много злости.":"يبدو أن هناك غضباً كثيراً الآن.","Похоже, сил сейчас совсем немного.":"يبدو أن طاقتك قليلة جداً الآن.","Похоже, сейчас одиноко.":"يبدو أنك تشعر بالوحدة الآن.","Похоже, это задело.":"يبدو أن هذا آلمك.","Похоже, рядом с этим есть чувство вины или стыда.":"يبدو أن معه شعوراً بالذنب أو الخجل.","Как хорошо это слышать!":"ما أجمل سماع ذلك!","Слышу, что это связано с работой.":"أفهم أن الأمر يتعلق بالعمل.","Слышу, что это связано с семьёй.":"أفهم أن الأمر يتعلق بالعائلة.","Слышу, что это связано с отношениями.":"أفهم أن الأمر يتعلق بالعلاقة.","Слышу, что это связано с друзьями.":"أفهم أن الأمر يتعلق بالأصدقاء.","Слышу, что это связано со здоровьем.":"أفهم أن الأمر يتعلق بالصحة.","Слышу, что это связано с деньгами.":"أفهم أن الأمر يتعلق بالمال.","Слышу, что это связано с учёбой.":"أفهم أن الأمر يتعلق بالدراسة.","Я слушаю. Что было дальше?":"أنا أستمع. ماذا حدث بعد ذلك؟","Это звучит непросто. Что сейчас ощущается сильнее всего?":"يبدو هذا صعباً. ما أقوى ما تشعر به الآن؟","Понимаю. Что для тебя здесь самое важное?":"أفهم. ما الأهم بالنسبة لك هنا؟","Спасибо, что рассказываешь. Как это на тебя повлияло?":"شكراً لأنك تحكي. كيف أثّر ذلك عليك؟","Если посмотреть на это со стороны — что хотелось бы изменить в первую очередь?":"إذا نظرت إليه من الخارج، ما الذي تود تغييره أولاً؟","Что помогло бы тебе хоть немного прямо сейчас?":"ما الذي قد يساعدك ولو قليلاً الآن؟","Злюсь":"غاضب","Одиноко":"وحيد","Всё хорошо":"كل شيء بخير","Куда сегодня сходить?":"إلى أين أذهب اليوم؟","Просто выговориться":"أن أفضفض فقط","Небольшой шаг, чтобы стало легче":"خطوة صغيرة لأرتاح","Потренировать трудный разговор":"التدرّب على محادثة صعبة","Куда сходить или что поесть":"إلى أين أذهب أو ماذا آكل","Привет. Я — «Рядом». Можно написать, как ты, своими словами или выбрать подсказку.":"مرحباً. أنا Ryadom. يمكنك أن تكتب كيف حالك بكلماتك أو تختار اقتراحاً.","На этом языке я понимаю простые фразы. Подсказки-кнопки помогут быть точнее.":"بهذه اللغة أفهم العبارات البسيطة. تساعد أزرار الاقتراحات على دقة أكبر.","Как хорошо это слышать! Что сегодня порадовало?":"ما أجمل سماع ذلك! ما الذي أسعدك اليوم؟","Куда сходить отметить?":"إلى أين أذهب للاحتفال؟","Записать в дневник":"اكتب في اليوميات","Есть и сложная часть":"هناك جزء صعب أيضاً","Что сейчас было бы полезнее?":"ما الأكثر فائدة الآن؟","Вот что можно попробовать. Любой шаг можно остановить.":"إليك ما يمكنك تجربته. يمكنك إيقاف أي خطوة.","Лучше просто поговорим":"لنتحدث فقط","Подобрать небольшой шаг":"اقترح خطوة صغيرة","Продолжу рассказывать":"سأتابع الحكي","Спасибо за разговор. Я здесь, когда захочется вернуться.":"شكراً على المحادثة. أنا هنا متى أردت العودة.","Начать новый разговор":"ابدأ محادثة جديدة","Открыть дневник":"افتح اليوميات","Похоже, сейчас очень много злости. Если есть риск навредить другому человеку — остановись и выйди из ситуации: на воздух, в другую комнату. Если опасность рядом — звони в экстренную службу.":"يبدو أن هناك غضباً كبيراً الآن. إن كان هناك خطر إيذاء شخص آخر، توقّف واخرج من الموقف: إلى الهواء الطلق أو غرفة أخرى. إن كان الخطر قريباً، اتصل بالطوارئ.","То, что ты описываешь, звучит небезопасно. Твоя безопасность важнее всего. Если опасность рядом прямо сейчас — постарайся уйти в безопасное место и позвони в экстренную службу.":"ما تصفه يبدو غير آمن. سلامتك أهم شيء. إن كان الخطر قريباً الآن، حاول الذهاب إلى مكان آمن واتصل بالطوارئ.","Спасибо, что ты об этом говоришь. Твоя безопасность сейчас важнее всего. С этим не нужно справляться без поддержки: позвони на линию помощи или человеку, которому доверяешь.":"شكراً لأنك تتحدث عن هذا. سلامتك أهم شيء الآن. لا داعي لأن تواجه هذا دون دعم: اتصل بخط مساعدة أو بشخص تثق به.","Показать текст для близкого":"اعرض نصاً لشخص قريب","Сейчас я в безопасности":"أنا بأمان الآن","Если опасность прямо сейчас — экстренная служба: 112 (в большинстве стран).":"إن كان هناك خطر الآن — الطوارئ: 112 (في معظم البلدان).","Линии помощи в других странах: findahelpline.com":"خطوط المساعدة في بلدان أخرى: findahelpline.com","Пожалуйста. Я рядом.":"على الرحب. أنا هنا.","Нет, я не врач и не психолог: не ставлю диагнозов и не лечу. Я помогаю выговориться, назвать, что происходит, и сделать небольшой шаг. Если тяжёлое состояние держится долго или мешает жить, стоит обратиться к специалисту.":"لا، لست طبيباً ولا أخصائياً نفسياً: لا أشخّص ولا أعالج. أساعدك على الفضفضة وتسمية ما يحدث واتخاذ خطوة صغيرة. إن استمرت حالة صعبة طويلاً أو أعاقت حياتك، فمن المفيد مراجعة مختص.","Я «Рядом» — программа, а не человек. Я не врач и не заменяю специалиста.":"أنا Ryadom — برنامج وليس إنساناً. لست طبيباً ولا أحل محل المختص.","Хорошо, не будем. Ничего объяснять не нужно. Можно просто побыть рядом или выбрать другое.":"حسناً، لن نفعل. لا داعي لشرح أي شيء. يمكننا أن نبقى معاً فقط أو نختار شيئاً آخر.","Я рядом. Начнём с самого простого: что сейчас ближе?":"أنا هنا. لنبدأ بالأبسط: ما الأقرب لما تشعر به الآن؟","Привет. Что сейчас происходит? Можно написать своими словами или выбрать подсказку.":"مرحباً. ماذا يحدث الآن؟ يمكنك الكتابة بكلماتك أو اختيار اقتراح.","Это стоит запомнить. Хочешь отметить это — сходить куда-нибудь или записать в дневник?":"هذا يستحق أن يُتذكَّر. هل تود أن تحتفل به — بالذهاب إلى مكان ما أو الكتابة في اليوميات؟","А что здесь сильнее всего?":"وما الأقوى هنا؟","Обида":"استياء","Усталость":"تعب","Хочу понять точнее. Что ближе всего к тому, что сейчас внутри? Можно выбрать подсказку.":"أريد أن أفهم بدقة أكبر. ما الأقرب لما في داخلك الآن؟ يمكنك اختيار اقتراح.","Из того, что известно о тебе:":"مما أعرفه عنك:","В разделе «Места» можно выбрать настроение и посмотреть, что рядом.":"في «الأماكن» يمكنك اختيار مزاج ورؤية ما هو قريب.","Открыть «Места»":"افتح «الأماكن»","Расскажу, что на душе":"سأحكي ما في قلبي","Расскажи, что ещё происходит.":"أخبرني بما يحدث أيضاً.","Я слушаю. Можно писать как получается — кусками, без порядка.":"أنا أستمع. يمكنك الكتابة كما يأتيك — على دفعات ودون ترتيب.","Тренажёры трудных разговоров пока доступны только на русском языке. Можно открыть их или выбрать другое.":"تمارين المحادثات الصعبة متاحة حالياً بالروسية فقط. يمكنك فتحها أو اختيار شيء آخر.","Открыть тренажёры":"افتح التمارين","Я слушаю.":"أنا أستمع.","Хорошо. Если станет хуже — линии помощи выше, и можно вернуться сюда в любой момент.":"حسناً. إن ساءت الحال، فخطوط المساعدة في الأعلى، ويمكنك العودة إلى هنا في أي وقت.","Можно отправить близкому:":"يمكنك أن ترسل إلى شخص قريب:","Мне сейчас очень тяжело. Пожалуйста, побудь со мной или позвони мне сейчас. Помоги обратиться за помощью.":"أمرّ بوقت صعب جداً الآن. أرجوك ابقَ معي أو اتصل بي الآن. ساعدني لأطلب المساعدة.","Хорошо, что стало хоть немного легче. Хочешь остановиться на этом или продолжить?":"من الجيد أن الأمر خفّ قليلاً. هل تود التوقف هنا أم المتابعة؟","Жаль, что стало тяжелее. Давай не продолжать эту практику. Можно связаться с близким человеком или выбрать другой, более мягкий шаг.":"آسف لأن الأمر أصبح أصعب. لنتوقف عن هذا التمرين. يمكنك التواصل مع شخص قريب أو اختيار خطوة أخرى ألطف.","Иногда эффект приходит не сразу. Можно попробовать другой способ или просто поговорить.":"أحياناً لا يظهر الأثر فوراً. يمكنك تجربة طريقة أخرى أو التحدث فقط.","Другой способ":"طريقة أخرى","Подобрано {x}. Можно выбрать любое или ничего.":"تم الاختيار: {x}. يمكنك اختيار أي منها أو لا شيء.","по последней отметке «{q}»":"بحسب آخر تسجيل لك «{q}»","по последней отметке «{q}» и позднему времени":"بحسب آخر تسجيل لك «{q}» والوقت المتأخر","{x} · Открыть →":"{x} · افتح ←","{0} из {1}":"{0} من {1}","Отметить шаг цепочки: {x}":"علّم خطوة السلسلة: {x}","Открыть практику: {x}":"افتح التمرين: {x}","Открыть тренажёр: {x}":"افتح التدريب: {x}","Убрать «{q}»":"إزالة «{q}»","Удалить: {x}":"حذف: {x}","Идея на сегодня: {x}.":"فكرة لليوم: {x}.","Идея на сегодня: {x}. Лучше без: {y}.":"فكرة لليوم: {x}. الأفضل من دون: {y}.","поесть":"أكل","побыть":"قضاء الوقت","{0} Б":"{0} بايت","{0} КБ":"{0} ك.ب","Данные восстановлены ({0}). Обновляю приложение…":"استُعيدت البيانات ({0}). جارٍ تحديث التطبيق…","Добавлено записей: {0}":"الإدخالات المضافة: {0}","тебе обычно подходит — {x}. Выбирай места с учётом этого.":"ما يناسبك عادةً — {x}. اختر الأماكن مع مراعاة ذلك.","тебе обычно подходит — {x}. Лучше без: {y}. Выбирай места с учётом этого.":"ما يناسبك عادةً — {x}. الأفضل من دون: {y}. اختر الأماكن مع مراعاة ذلك.","{0} м":"{0} م","{0} км":"{0} كم","Убрать из любимых: {x}":"إزالة من المفضلة: {x}","В любимые: {x}":"إلى المفضلة: {x}","«{q}» добавлено в дневник за сегодня.":"أُضيف «{q}» إلى يوميات اليوم.","Ищем места рядом с «{q}»…":"نبحث عن أماكن قرب «{q}»…","Ищем «{q}»…":"نبحث عن «{q}»…","Сохранён город «{q}». Выбирай настроение — подборка обновится.":"حُفظت المدينة «{q}». اختر مزاجاً — ستتحدّث القائمة.","Найдено практик: {0} из {1}":"التمارين التي عُثر عليها: {0} من {1}","Показать ещё ({0})":"عرض المزيد ({0})","В диалоге: {x}":"في المحادثة: {x}","Удалить тексты разговоров за {x}? Отметки состояния останутся.":"حذف نصوص محادثات {x}؟ ستبقى تسجيلات الحالة.","Практики: {x}":"التمارين: {x}","Шаг {0} из {1}":"الخطوة {0} من {1}","Подсказка: {x}":"تلميح: {x}","Источник: {x}":"المصدر: {x}","Пройдено стилей: {0} из {1}":"الأساليب المكتملة: {0} من {1}","День {0}":"اليوم {0}","{x} по дням":"{x} حسب الأيام","Готово: каждый день в {0}:{1}. Пропускать можно — это просто приглашение.":"تم: كل يوم في {0}:{1}. لا بأس بالتخطي — إنها مجرد دعوة.","Чаще всего тебе помогала практика «{q}» ({0} раз). Это личная заметка, не медицинский вывод.":"التمرين الذي ساعدك أكثر من غيره هو «{q}» ({0} مرات). هذه ملاحظة شخصية وليست استنتاجاً طبياً.","Удалить «{q}» из этого дня?":"حذف «{q}» من هذا اليوم؟","{0} место":"{0} مكان","{0} места":"{0} أماكن","{0} мест":"{0} مكاناً","Играть: {x}":"العب: {x}","{0} мин":"{0} د","{0} минуты":"{0} دقائق","{0} минут":"{0} دقيقة","{0} минута":"{0} دقيقة","{0}–{1} минут":"{0}–{1} دقائق","рядом":"ryadom","Я":"أنا","на каждый день":"لكل يوم","← К играм":"→ إلى الألعاب",". Оценки и популярность в соцсетях появятся только после подключения проверенного источника данных.":". ستظهر التقييمات والشعبية على وسائل التواصل فقط بعد ربط مصدر بيانات موثوق.","есть разговор":"توجد محادثة","есть отметка состояния":"يوجد تسجيل حالة","есть посещённые места":"توجد أماكن تمت زيارتها","Квесты и сюжетные игры пока доступны только на русском языке. Перевод появится в следующих версиях.":"المهام والألعاب القصصية متاحة حالياً بالروسية فقط. ستأتي الترجمة في الإصدارات القادمة.","Не знаю, как сказать":"لا أعرف كيف أقول ذلك","Если сейчас очень тяжело":"إن كان الأمر صعباً جداً الآن","С этим не нужно справляться в одиночку. Выбери то, что получится сейчас.":"لا داعي لأن تواجه هذا وحدك. اختر ما تستطيع فعله الآن.","Позвонить":"اتصل","Написать близкому":"اكتب لشخص قريب","Мне сейчас очень тяжело. Пожалуйста, позвони мне или побудь рядом. Помоги мне получить помощь.":"أمرّ بوقت صعب جداً الآن. أرجوك اتصل بي أو ابقَ معي. ساعدني لأحصل على المساعدة.","Пережить ближайшие минуты":"تجاوز الدقائق القليلة القادمة","Медленный выдох длиннее вдоха. Назови пять вещей, которые видишь вокруг. Если рядом есть что-то опасное — отложи это подальше или выйди в другое место.":"أخرج النفس ببطء، أطول من الشهيق. سمِّ خمسة أشياء تراها حولك. إن كان قربك شيء خطير، أبعده أو اذهب إلى مكان آخر.","Дыхание вместе со мной":"تنفّس معي","Мой план безопасности":"خطة الأمان الخاصة بي","Заполни, когда немного спокойнее. План останется только на этом устройстве и откроется здесь в трудную минуту.":"املأها عندما تكون أهدأ قليلاً. تبقى الخطة على هذا الجهاز فقط وستفتح هنا في اللحظة الصعبة.","Как я понимаю, что мне становится хуже":"كيف أعرف أن حالتي تسوء","Что помогает мне хоть немного":"ما يساعدني ولو قليلاً","Кому могу написать или позвонить":"من يمكنني مراسلته أو الاتصال به","Как сделать обстановку вокруг безопаснее":"كيف أجعل محيطي أكثر أماناً","«Рядом» — не экстренная служба и может не распознать, что тебе плохо. Если есть риск для жизни, звони 112 или обратись к человеку рядом.":"Ryadom ليس خدمة طوارئ وقد لا يدرك أنك لست بخير. إن كان هناك خطر على الحياة فاتصل بـ 112 أو توجّه إلى شخص قريب.","Мне очень плохо":"أنا لست بخير أبداً","Мне сейчас очень плохо — открыть помощь":"أنا لست بخير الآن — افتح المساعدة","Открыть экран помощи":"افتح شاشة المساعدة","Прежде чем продолжить, хочу спросить прямо, потому что это важно: ты сейчас думаешь о том, чтобы причинить себе вред или не жить?":"قبل أن نتابع، أريد أن أسأل مباشرة لأن هذا مهم: هل تفكر الآن في إيذاء نفسك أو في ألا تعيش؟","Да":"نعم","Не знаю":"لا أعرف","Нет, это другое":"لا، إنه أمر آخر","Спасибо за ответ. Продолжим.":"شكراً على إجابتك. لنتابع."},"lex":{"emo":{"fear":["قلق","خائف","خوف","متوتر","توتر","ذعر","هلع"],"sad":["حزين","حزن","أبكي","ابكي","بكاء","مكتئب","اكتئاب","ضيق"],"anger":["غاضب","غضب","زعلان","عصبي","منزعج","أكره","اكره"],"tired":["متعب","تعبان","تعب","مرهق","إرهاق","منهك","لا طاقة"],"lonely":["وحيد","وحدة","لا أحد","لا احد"],"hurt":["مجروح","جرحني","إهانة","اهانة","خيانة","خانني","مهان"],"shame":["خجل","عار","ذنب","محرج"],"good":["بخير","جيد","سعيد","رائع","مرتاح","ممتاز","الحمد لله"]},"theme":{"work":["عمل","شغل","وظيفة","مدير","زميل","المكتب"],"family":["عائلة","أمي","أبي","ابي","والد","أخي","اخي","أختي","اختي","ابني","بنتي","أهلي","اهلي"],"love":["حبيب","زوج","زوجة","خطيب","علاقة","انفصال"],"friends":["صديق","أصدقاء","اصدقاء"],"health":["صحة","مريض","مرض","ألم","طبيب","مستشفى"],"money":["فلوس","ديون","راتب","إيجار","ايجار","قرض"],"study":["مدرسة","امتحان","دراسة","جامعة","الأستاذ","معلم"]},"intent":{"bye":["مع السلامة","وداعا","إلى اللقاء","تصبح على خير"],"thanks":["شكرا","شكراً","مشكور"],"doctor":["هل أنت طبيب","هل انت طبيب","طبيب نفسي","معالج"],"who":["من أنت","من انت","هل أنت إنسان","هل انت انسان","روبوت"],"hello":["مرحبا","السلام عليكم","أهلا","اهلا","هلا"],"help":["ساعدني","ماذا أفعل","ماذا افعل"],"go":["إلى أين أذهب","وين أروح","وين اروح","أخرج","ماذا آكل"],"nowant":["لا أريد","لا اريد","اتركني","توقف"]}},"help":{"lines":[]}};
